import { requireHttpPolicy } from "../policy/normalize.js";
import { HTTP_PACKAGE_NAME, HTTP_PACKAGE_VERSION } from "../package-version.js";
import { projectHttpPublicErrors } from "../handler/public-errors.js";
import { projectHttpCookies } from "./cookie-projection.js";
/** Derive the browser-visible contract from the same policy used by the handler. */
export function httpWire(options) {
    const policy = requireHttpPolicy(options.policy, "httpWire");
    const name = options.name;
    return Object.freeze({
        provenance: Object.freeze({ name: HTTP_PACKAGE_NAME, version: HTTP_PACKAGE_VERSION }),
        project(facts) {
            const projected = projectHttpPublicErrors(structuredClone(facts.logicalWire), policy);
            return {
                name,
                wire: policy.cookies === undefined ? projected : projectHttpCookies(facts, policy, projected),
                render: { appWideErrorName: "HttpAppWideError" },
            };
        },
    });
}
